from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent.parent/'rain-coupled-reference'))
import model as m
import numpy as np

def body_response(x):
 force=np.zeros(m.ndof)
 for b in m.blocks:force+=b['J'].T@x[b['sl']]
 return m.M@force

def gradient(x):
 velocity=m.vfree+body_response(x);out=np.zeros(m.offset)
 for b in m.blocks:
  sl=b['sl'];out[sl]=b['J']@velocity+b['bias']+b['G']@x[sl]
 return out

class Operator:
 def __init__(self,x):
  self.x=x.copy();grad=gradient(x);self.rows=[];self.value=np.zeros(m.offset);self.calls=0
  for b in m.blocks:
   sl=b['sl'];n=sl.stop-sl.start;I=np.eye(n);step=b['step'];z=x[sl]-step*grad[sl];domain=b['domain'];P=z.copy();Dz=I.copy();Dc=np.zeros(n)
   if domain=='positive':P=np.maximum(z,0);Dz=np.diag((z>0).astype(float))
   elif domain=='box':
    r=m.radius(b,x);P=np.clip(z,-r,r);Dz=np.diag((abs(z)<r).astype(float));Dc=np.where(abs(z)>=r,np.sign(z),0)
   elif domain=='ball':
    r=m.radius(b,x);length=np.linalg.norm(z)
    if length>r:
     u=z/length;P=r*u;Dz=(r/length)*(I-np.outer(u,u));Dc=u
   self.value[sl]=x[sl]-P
   dependency=b['normal_indices'] is not None and m.radius(b,x)>0
   local=I-Dz@(I-step*(b['K']+b['G']));inverse=np.linalg.inv(local)
   self.rows.append((b,Dz,Dc,dependency,local,inverse))
 def apply(self,p,include_softness=True,include_bounds=True):
  self.calls+=1;dv=body_response(p);out=np.zeros(m.offset)
  for b,Dz,Dc,dependency,_,_ in self.rows:
   sl=b['sl'];dg=b['J']@dv
   if include_softness:dg+=b['G']@p[sl]
   out[sl]=p[sl]-Dz@(p[sl]-b['step']*dg)
   if dependency and include_bounds:out[sl]-=Dc*(b['weights']@p[b['normal_indices']])
  return out
 def adjoint(self,p):
  t=np.zeros(m.offset);out=np.zeros(m.offset)
  for b,Dz,Dc,dependency,_,_ in self.rows:
   sl=b['sl'];t[sl]=b['step']*(Dz.T@p[sl]);out[sl]=p[sl]-Dz.T@p[sl]+b['G'].T@t[sl]
   if dependency:out[b['normal_indices']]-=b['weights']*(Dc@p[sl])
  dv=body_response(t)
  for b in m.blocks:out[b['sl']]+=b['J']@dv
  return out
 def precondition(self,p):
  out=np.zeros(m.offset)
  for b,_,_,_,_,inverse in self.rows:out[b['sl']]=inverse@p[b['sl']]
  return out

