from pathlib import Path
import json,time
import numpy as np
from scipy.sparse.linalg import LinearOperator,gmres
from nk_operator import Operator,m,gradient,body_response
from wave import wave
p=Path(__file__).resolve().parent;assert json.loads((p/'controls.json').read_text())['status']=='controls-pass';all_results={};reference=np.load(m.p/'polished-solution.npz')
class Budget(Exception):pass
for name,initial in [('cold',np.zeros(m.offset)),('capped',m.old.copy())]:
 x=initial.copy();records=[];start=time.monotonic();reason='newton-step-cap';total_actions=0;total_adjoints=0;total_merit=0
 for iteration in range(16):
  op=Operator(x);r=op.value;natural=float(np.max(abs(r)/(1+abs(x))))
  if natural<=1e-10:reason='strict-natural-residual';break
  eta=min(.1,max(1e-6,np.sqrt(natural)));history=[]
  def action(v):
   if op.calls>=160:raise Budget('160Jacobian-actions-per-step')
   return op.apply(v)
  A=LinearOperator((m.offset,m.offset),matvec=action,dtype=float);M=LinearOperator((m.offset,m.offset),matvec=op.precondition,dtype=float)
  try:dx,info=gmres(A,-r,M=M,restart=32,maxiter=4,rtol=eta,atol=1e-13,callback=lambda v:history.append(float(v)),callback_type='pr_norm')
  except Budget as e:reason=str(e);total_actions+=op.calls;break
  derivative=op.apply(dx);slope=float(r@derivative);fallback=False
  if slope>=0:
   dx=-op.adjoint(r);total_adjoints+=1;derivative=op.apply(dx);slope=float(r@derivative);fallback=True
  merit=.5*float(r@r);accepted=False
  for backtrack in range(8):
   alpha=2.**-backtrack;trial=x+alpha*dx;trial_operator=Operator(trial);total_merit+=1;rr=trial_operator.value
   if .5*float(rr@rr)<=merit+1e-4*alpha*slope and slope<0:accepted=True;break
  row=dict(iteration=iteration+1,initial_relative_natural_residual=natural,forcing_relative_tolerance=float(eta),gmres_info=int(info),krylov_iterations=len(history),jacobian_actions=op.calls,true_linear_relative_residual=float(np.linalg.norm(derivative+r)/max(np.linalg.norm(r),1e-300)),gradient_fallback=fallback,accepted=accepted,alpha=alpha if accepted else 0.,backtracks=backtrack,merit_slope=slope)
  total_actions+=op.calls;records.append(row);print(name,json.dumps(row),flush=True)
  if not accepted:reason='line-search-failed';break
  x=trial
 natural=float(np.max(abs(m.residual(x))/(1+abs(x))));primal=gradient(x);dense=m.H@x+m.g;agreement=float(np.max(abs(primal-dense)/(1+np.maximum(abs(primal),abs(dense)))));_,sweep=wave(x);feas=[]
 for b in m.blocks:
  val=x[b['sl']];domain=b['domain'];cap=m.radius(b,x);error=0.
  if domain=='positive':error=max(0,-float(min(val)))
  elif domain=='box':error=max(0,float(max(abs(val)))-cap)/(1+cap)
  elif domain=='ball':error=max(0,float(np.linalg.norm(val))-cap)/(1+cap)
  feas.append(error)
 passed=bool(natural<=1e-8 and max(feas)<=1e-8 and agreement<=1e-9 and max(sweep['max_velocity_change'],sweep['max_impulse_change'])<=1e-5)
 result=dict(status='prototype-pass' if passed else 'prototype-failed',termination=reason,seconds=time.monotonic()-start,newton_steps=len(records),jacobian_actions=total_actions,adjoint_actions=total_adjoints,merit_evaluations=total_merit,final_relative_natural_residual=natural,maximum_scaled_feasibility_violation=max(feas),direct_primal_agreement=agreement,final_colored_sweep=sweep,reference_velocity_max_difference=float(np.max(abs(m.vfree+body_response(x)-reference['velocities']))),reference_impulse_max_difference=float(np.max(abs(x-reference['impulses']))),iterations=records)
 all_results[name]=result;np.savez(p/(name+'-solution.npz'),impulses=x,velocities=m.vfree+body_response(x));(p/'result.json').write_text(json.dumps(dict(scope='Float64 reconstructed cold/capped fixed-geometry matrix-free prototype; not actual phase-entry/GPU/physical qualification.',arms=all_results),indent=2));print(name,'FINAL',json.dumps({k:v for k,v in result.items() if k!='iterations'}),flush=True)
if not all(r['status']=='prototype-pass' for r in all_results.values()):raise SystemExit(1)

