from pathlib import Path
import json,time,numpy as np
from scipy.sparse.linalg import LinearOperator,gmres
from nk_operator import Operator,m,gradient,body_response
from wave import wave
p=Path(__file__).resolve().parent;all_results={};reference=np.load(m.p/'polished-solution.npz')
class Budget(Exception):pass
for name,initial in [('cold',np.zeros(m.offset)),('capped',m.old.copy())]:
 x=initial.copy();sigma=1.;records=[];accepted_count=0;total_actions=0;start=time.monotonic();reason='accepted-step-cap'
 for step in range(32):
  op=Operator(x);r=op.value;natural=float(np.max(abs(r)/(1+abs(x))))
  if natural<=1e-10:reason='strict-natural-residual';break
  eta=min(.1,max(1e-6,np.sqrt(natural)));accepted=False
  for regularization_trial in range(8):
   if len(records)>=64:reason='linear-trial-cap';break
   op.calls=0;inverses=[np.linalg.inv(local+sigma*np.eye(local.shape[0])) for _,_,_,_,local,_ in op.rows]
   def action(v):
    if op.calls>=160:raise Budget('160Jacobian-actions-per-trial')
    return op.apply(v)+sigma*v
   def precondition(v):
    result=np.zeros(m.offset)
    for row,inverse in zip(op.rows,inverses):b=row[0];result[b['sl']]=inverse@v[b['sl']]
    return result
   history=[]
   try:dx,info=gmres(LinearOperator((m.offset,m.offset),matvec=action,dtype=float),-r,M=LinearOperator((m.offset,m.offset),matvec=precondition,dtype=float),restart=32,maxiter=4,rtol=eta,atol=1e-13,callback=lambda v:history.append(float(v)),callback_type='pr_norm')
   except Budget as e:reason=str(e);total_actions+=op.calls;break
   derivative=op.apply(dx);predicted=.5*float(r@r-(r+derivative)@(r+derivative));trial=x+dx;rr=Operator(trial).value;actual=.5*float(r@r-rr@rr);ratio=actual/predicted if predicted>0 else -1e300;accepted=predicted>0 and actual>0 and ratio>=.1
   record=dict(trial=len(records)+1,step=step+1,sigma=sigma,initial_relative_natural_residual=natural,gmres_info=int(info),krylov_iterations=len(history),jacobian_actions=op.calls,true_shifted_relative_residual=float(np.linalg.norm(derivative+sigma*dx+r)/max(np.linalg.norm(r),1e-300)),predicted_decrease=predicted,actual_decrease=actual,ratio=ratio,accepted=accepted)
   records.append(record);total_actions+=op.calls;print(name,json.dumps(record),flush=True)
   if accepted:
    x=trial;accepted_count+=1
    if ratio>.75:sigma=max(1e-12,sigma*.5)
    elif ratio<.25:sigma*=2
    break
   sigma*=4
  if not accepted:
   if reason=='accepted-step-cap':reason='regularization-trial-cap'
   break
 natural=float(np.max(abs(m.residual(x))/(1+abs(x))));primal=gradient(x);dense=m.H@x+m.g;agreement=float(np.max(abs(primal-dense)/(1+np.maximum(abs(primal),abs(dense)))));_,sweep=wave(x);feas=[]
 for b in m.blocks:
  val=x[b['sl']];domain=b['domain'];cap=m.radius(b,x);error=0.
  if domain=='positive':error=max(0,-float(min(val)))
  elif domain=='box':error=max(0,float(max(abs(val)))-cap)/(1+cap)
  elif domain=='ball':error=max(0,float(np.linalg.norm(val))-cap)/(1+cap)
  feas.append(error)
 passed=bool(natural<=1e-8 and max(feas)<=1e-8 and agreement<=1e-9 and max(sweep['max_velocity_change'],sweep['max_impulse_change'])<=1e-5)
 result=dict(status='prototype-pass' if passed else 'prototype-failed',termination=reason,seconds=time.monotonic()-start,accepted_steps=accepted_count,linear_trials=len(records),jacobian_actions=total_actions,final_sigma=sigma,final_relative_natural_residual=natural,maximum_scaled_feasibility_violation=max(feas),direct_primal_agreement=agreement,final_colored_sweep=sweep,reference_velocity_max_difference=float(np.max(abs(m.vfree+body_response(x)-reference['velocities']))),reference_impulse_max_difference=float(np.max(abs(x-reference['impulses']))),trials=records)
 all_results[name]=result;np.savez(p/(name+'-trust-solution.npz'),impulses=x,velocities=m.vfree+body_response(x));(p/'trust-result.json').write_text(json.dumps(dict(scope='Float64 fixed-geometry trust-controlled matrix-free prototype; numerical step shift is absent from final residual checks.',arms=all_results),indent=2));print(name,'FINAL',json.dumps({k:v for k,v in result.items() if k!='trials'}),flush=True)
if not all(r['status']=='prototype-pass' for r in all_results.values()):raise SystemExit(1)
